@if(store_setting('tracking_enabled',false) && app(\App\Domain\Content\Actions\StorefrontOverlay::class)->allowed(request()))
<section x-data="{
 choice:@js(session('tracking_choice')),busy:false,open:@js(session('tracking_choice')===null),error:'',
 async choose(accepted){this.busy=true;try{let r=await fetch(@js(route('tracking.consent')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@js(csrf_token())},body:JSON.stringify({accepted})});if(!r.ok)throw Error();try{localStorage.setItem('store-tracking-choice',String(Date.now()))}catch(e){}location.reload()}catch(e){this.error=@js(__('marketing.tracking_failed'))}finally{this.busy=false}},
 async init(){if(this.choice!==true)return;try{let r=await fetch(@js(route('tracking.events')),{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':@js(csrf_token())}});if(!r.ok)return;let body=await r.json();this.start(body.config||{},body.events||[])}catch(e){}},
 start(config,events){
 const load=url=>{let s=document.createElement('script');s.async=true;s.src=url;document.head.appendChild(s)};
 window.dataLayer=window.dataLayer||[];window.gtag=window.gtag||function(){dataLayer.push(arguments)};
 if(config.ga4){gtag('consent','default',{analytics_storage:'granted',ad_storage:'granted',ad_user_data:'granted',ad_personalization:'granted'});gtag('js',new Date());gtag('config',config.ga4,{send_page_view:false});load('https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(config.ga4))}
 if(config.gtm){dataLayer.push({'gtm.start':Date.now(),event:'gtm.js'});load('https://www.googletagmanager.com/gtm.js?id='+encodeURIComponent(config.gtm))}
 if(config.meta){window.fbq=window.fbq||function(){fbq.callMethod?fbq.callMethod.apply(fbq,arguments):fbq.queue.push(arguments)};fbq.queue=fbq.queue||[];fbq.loaded=true;fbq.version='2.0';fbq('init',config.meta);fbq('set','autoConfig',false,config.meta);load('https://connect.facebook.net/en_US/fbevents.js')}
 if(config.tiktok){window.TiktokAnalyticsObject='ttq';window.ttq=window.ttq||[];for(let method of ['track','page','identify','instances','debug','on','off','once','ready','alias','group','enableCookie','disableCookie'])if(!ttq[method])ttq[method]=function(){ttq.push([method,...arguments])};ttq._i=ttq._i||{};ttq._i[config.tiktok]=[];ttq._i[config.tiktok]._u='https://analytics.tiktok.com/i18n/pixel/events.js';ttq._t=ttq._t||{};ttq._t[config.tiktok]=Date.now();ttq._o=ttq._o||{};ttq._o[config.tiktok]={};load('https://analytics.tiktok.com/i18n/pixel/events.js?sdkid='+encodeURIComponent(config.tiktok)+'&amp;lib=ttq')}
 for(let event of events){let params={...event.data,event_id:event.id};if(config.meta)fbq('track',event.name,event.data,{eventID:event.id});if(config.ga4){let names={ViewContent:'view_item',AddToCart:'add_to_cart',InitiateCheckout:'begin_checkout',Purchase:'purchase'};let ga={...params,currency:params.currency,value:params.value,items:(params.content_ids||[]).map(id=>({item_id:id,quantity:params.quantity||1}))};if(event.name==='Purchase')ga.transaction_id=event.id;gtag('event',names[event.name],ga)}if(config.gtm)dataLayer.push({event:'commerce_'+event.name,...params});if(config.tiktok)ttq.track(event.name,event.data,{event_id:event.id})}
 }
}" @storage.window="if($event.key==='store-tracking-choice')location.reload()">
<button type="button" @click="open=true" class="mx-5 my-3 min-h-11 underline">{{ __('marketing.privacy_choices') }}</button>
<div x-show="open" x-cloak class="fixed bottom-0 inset-x-0 z-[90] border-t bg-white p-5 shadow-lg" role="region" aria-label="{{ __('marketing.tracking_consent') }}">
<div class="mx-auto flex max-w-6xl flex-wrap items-center gap-4"><div class="max-w-2xl"><h2 class="font-semibold">{{ __('marketing.tracking_consent') }}</h2><p class="text-sm">{{ __('marketing.tracking_notice') }}</p><p x-text="error" role="alert"></p></div><button type="button" @click="choose(false)" :disabled="busy" class="btn-secondary">{{ __('marketing.reject_tracking') }}</button><button type="button" @click="choose(true)" :disabled="busy" class="btn-primary">{{ __('marketing.accept_tracking') }}</button><button type="button" x-show="choice!==null" @click="open=false" class="min-h-11 px-4">{{ __('store.close') }}</button></div>
</div></section>
@endif
